static void sift_down_max(int *a, int n, int i) {
    for (;;) {
        int l = 2*i+1, r = 2*i+2, big = i;
        if (l < n && a[l] > a[big]) big = l;
        if (r < n && a[r] > a[big]) big = r;
        if (big == i) break;
        int t=a[i]; a[i]=a[big]; a[big]=t;
        i = big;
    }
}
void heap_build_max(int *a, int n) {
    for (int i = n/2 - 1; i >= 0; --i)
        sift_down_max(a, n, i);
}

static void sift_up_max(int *a, int i) {
    while (i > 0) {
        int p = (i-1)/2;
        if (a[p] >= a[i]) break;
        int t=a[p]; a[p]=a[i]; a[i]=t;
        i = p;
    }
}
void max_heap_push(int *a, int *n, int val) {
    a[*n] = val; sift_up_max(a, *n); (*n)++;
}
int max_heap_pop(int *a, int *n) {
    int top = a[0];
    a[0] = a[--(*n)];
    sift_down_max(a, *n, 0);
    return top;
}

void heap_sort(int *a, int n) {
    heap_build_max(a, n);
    for (int end = n-1; end > 0; --end) {
        int t=a[0]; a[0]=a[end]; a[end]=t;
        sift_down_max(a, end, 0);
    }
}

int kth_largest(const int *a, int n, int k) {
    int *h = malloc((size_t)k * sizeof *h);
    int hn = 0;
    for (int i = 0; i < n; ++i) {
        if (hn < k) { h[hn]=a[i]; sift_up_min(h,hn); hn++; }
        else if (a[i] > h[0]) { h[0]=a[i]; sift_down_min(h,k,0); }
    }
    int res = h[0];
    free(h);
    return res;
}

typedef struct { int val, cnt; } vc_t;
int top_k_frequent(const int *a, int n, int k, int *out) {
    vc_t *f = malloc((size_t)(n?n:1)*sizeof *f);
    int m = 0;
    for (int i=0;i<n;++i){int j=0;for(;j<m;++j)if(f[j].val==a[i]){f[j].cnt++;break;}
        if(j==m){f[m].val=a[i];f[m].cnt=1;m++;}}
    if (k>m) k=m;
    vc_t *h = malloc((size_t)(k?k:1)*sizeof *h); int hn=0;
    for (int i=0;i<m;++i){
        if(hn<k){h[hn]=f[i];vc_sift_up(h,hn);hn++;}
        else if(f[i].cnt>h[0].cnt){h[0]=f[i];vc_sift_down(h,k,0);}
    }
    for (int i=k-1;i>=0;--i){out[i]=h[0].val; h[0]=h[hn-1]; hn--; vc_sift_down(h,hn,0);}
    free(h); free(f); return k;
}

typedef struct { int val, ai, ei; } m6_t;
int merge_k_sorted(const int *const *arrs, const int *lens, int k, int *out) {
    m6_t *h = malloc((size_t)(k?k:1)*sizeof *h); int hn=0;
    for (int i=0;i<k;++i) if(lens[i]>0){
        h[hn].val=arrs[i][0]; h[hn].ai=i; h[hn].ei=0; m6_sift_up(h,hn); hn++; }
    int idx=0;
    while (hn>0){
        m6_t t=h[0]; out[idx++]=t.val; int ne=t.ei+1;
        if(ne<lens[t.ai]){ h[0].val=arrs[t.ai][ne]; h[0].ai=t.ai; h[0].ei=ne; }
        else { h[0]=h[hn-1]; hn--; }
        m6_sift_down(h,hn,0);
    }
    free(h); return idx;
}

typedef struct { int id, priority; } task_t;
int robot_swarm_schedule(const task_t *tasks, int n, int decay, int *order, int cap) {
    task_t *h = malloc((size_t)(n?n:1)*sizeof *h); int hn=0;
    for (int i=0;i<n;++i){ h[hn]=tasks[i]; task_sift_up(h,hn); hn++; }
    int steps=0;
    while (hn>0 && steps<cap) {
        task_t top=h[0]; h[0]=h[hn-1]; hn--; task_sift_down(h,hn,0);
        order[steps++]=top.id;
        top.priority -= decay;
        if (top.priority > 0) { h[hn]=top; task_sift_up(h,hn); hn++; }
    }
    free(h); return steps;
}

void median_add(median_t *m, int v) {
    if (m->lo_n==0 || v<=m->lo[0]) { m->lo[m->lo_n]=v; sift_up_max(m->lo,m->lo_n); m->lo_n++; }
    else { m->hi[m->hi_n]=v; sift_up_min(m->hi,m->hi_n); m->hi_n++; }
    if (m->lo_n > m->hi_n+1) {
        int t=m->lo[0]; m->lo[0]=m->lo[--m->lo_n]; sift_down_max(m->lo,m->lo_n,0);
        m->hi[m->hi_n]=t; sift_up_min(m->hi,m->hi_n); m->hi_n++;
    } else if (m->hi_n > m->lo_n) {
        int t=m->hi[0]; m->hi[0]=m->hi[--m->hi_n]; sift_down_min(m->hi,m->hi_n,0);
        m->lo[m->lo_n]=t; sift_up_max(m->lo,m->lo_n); m->lo_n++;
    }
}
double median_get(const median_t *m) {
    if (m->lo_n==0) return 0.0;
    if (m->lo_n==m->hi_n) return (m->lo[0]+m->hi[0])/2.0;
    return (double)m->lo[0];
}
